//
// Whole-model generators for the references (CMS-02): a continuous model as a Modelica model, and as an
// ngspice netlist in which each state is a node voltage across a 1 F capacitor charged by a behavioural
// current source equal to its derivative (C dv/dt = i). Readers take the generated text back to
// { state: syntax tree }, so the test of T-32 compares trees read out of the whole generated files.
// Generated text carries the model hash and the generator version, never a timestamp.

import { SubcoreError } from './errors.js';
import { parse, parseModelica, parseSpice, toModelica, toSpice, INDEPENDENT } from './expr.js';
import { specHash } from './spec.js';
import { toSI } from './units.js';

export const EXPORT_VERSION = '1.0.0';
const NOTICE = '© 1993–2026 Abhishek Choudhary. All rights reserved. AyeAI.';

export function modelicaName(id) { return id.replace(/[^A-Za-z0-9_]/g, '_'); }

function num(x) {
  if (!Number.isFinite(x)) throw new SubcoreError('EXPORT', String(x), 'not finite');
  const s = String(x);
  return s.startsWith('-') ? `(${s})` : s;
}

// Modelica model text. Values in SI. The independent variable is Modelica's time.
export function modelToModelica(m) {
  if (m.kind !== 'continuous') throw new SubcoreError('EXPORT', 'kind', 'only continuous models are exported');
  const name = modelicaName(m.identity.id);
  const L = [
    `// ${NOTICE}`,
    '// SPDX-License-Identifier: CC0-1.0',
    `// Generated by subcore export.js ${EXPORT_VERSION} from model ${m.identity.id} ${m.identity.version}, sha256 ${specHash(m)}`,
    `model ${name} "${m.identity.title}"`,
  ];
  for (const p of m.parameters || []) L.push(`  parameter Real ${p.name} = ${num(toSI(p.value, p.unit))};`);
  for (const s of m.states) L.push(`  Real ${s.name}(start = ${num(toSI(s.initial, s.unit))}, fixed = true);`);
  for (const u of m.inputs || []) L.push(`  Real ${u.name};`);
  L.push('equation');
  for (const u of m.inputs || []) L.push(`  ${u.name} = ${toModelica(parse(u.expression))};`);
  for (const e of m.equations) L.push(`  der(${e.der}) = ${toModelica(parse(e.expression))};`);
  L.push(`end ${name};`);
  return L.join('\n') + '\n';
}

// Reads the equation section of a generated Modelica model: { der: { state: ast }, inputs: { name: ast } }
export function readModelica(text) {
  const der = {}, inputs = {};
  const body = text.split('\nequation\n')[1];
  if (!body) throw new SubcoreError('EXPORT', 'modelica', 'no equation section');
  for (const line of body.split('\n')) {
    const l = line.trim();
    if (l === '' || l.startsWith('end ')) continue;
    let m = /^der\(([A-Za-z_][A-Za-z0-9_]*)\) = (.*);$/.exec(l);
    if (m) { der[m[1]] = parseModelica(m[2]); continue; }
    m = /^([A-Za-z_][A-Za-z0-9_]*) = (.*);$/.exec(l);
    if (m) { inputs[m[1]] = parseModelica(m[2]); continue; }
    throw new SubcoreError('EXPORT', 'modelica', `unrecognised equation line '${l}'`);
  }
  return { der, inputs };
}

// ngspice netlist. Each state x: node x, C_x from x to 0 of 1 F, B_x from 0 to x with I = dx/dt, and an
// initial condition .ic v(x)=x0. Inputs are behavioural voltage sources. Parameters are .param lines.
// opts: { tstep, tstop, out } with out the wrdata file name.
export function modelToSpice(m, opts = {}) {
  if (m.kind !== 'continuous') throw new SubcoreError('EXPORT', 'kind', 'only continuous models are exported');
  const nodes = [...m.states.map((s) => s.name), ...(m.inputs || []).map((u) => u.name)];
  const hz = m.horizon || {};
  const tstop = opts.tstop ?? toSI(hz.t1, hz.unit || 's');
  const tstep = opts.tstep ?? (m.solver_defaults && m.solver_defaults.rk4_step) ?? tstop / 1000;
  const L = [
    `* ${NOTICE}`,
    '* SPDX-License-Identifier: CC0-1.0',
    `* Generated by subcore export.js ${EXPORT_VERSION} from model ${m.identity.id} ${m.identity.version}, sha256 ${specHash(m)}`,
  ];
  for (const p of m.parameters || []) L.push(`.param ${p.name}=${String(toSI(p.value, p.unit))}`);
  for (const u of m.inputs || []) L.push(`Bin_${u.name} ${u.name} 0 V=${toSpice(parse(u.expression), nodes)}`);
  for (const e of m.equations) {
    L.push(`C_${e.der} ${e.der} 0 1`);
    L.push(`B_${e.der} 0 ${e.der} I=${toSpice(parse(e.expression), nodes)}`);
  }
  L.push(`.ic ${m.states.map((s) => `v(${s.name})=${String(toSI(s.initial, s.unit))}`).join(' ')}`);
  L.push(`.tran ${tstep} ${tstop} 0 ${tstep} uic`);
  L.push('.control', 'set wr_singlescale', 'set wr_vecnames', 'option numdgt=17', 'run',
    `wrdata ${opts.out || 'out.txt'} ${m.states.map((s) => `v(${s.name})`).join(' ')}`, '.endc', '.end');
  return L.join('\n') + '\n';
}

// Reads the behavioural sources of a generated netlist: { der: { state: ast }, inputs: { name: ast } }
export function readSpice(text) {
  const der = {}, inputs = {};
  for (const line of text.split('\n')) {
    let m = /^B_([A-Za-z_][A-Za-z0-9_]*) 0 \1 I=(.*)$/.exec(line);
    if (m) { der[m[1]] = parseSpice(m[2]); continue; }
    m = /^Bin_([A-Za-z_][A-Za-z0-9_]*) \1 0 V=(.*)$/.exec(line);
    if (m) inputs[m[1]] = parseSpice(m[2]);
  }
  return { der, inputs };
}

export { INDEPENDENT };
